data=json.load(urllib.request.urlopen(req, timeout=30))
refs=[]
def walk(x):
    if isinstance(x, dict):
        name=x.get('name')
        if name=='ref_file' and 'options' in x:
            for o in x['options']:
                refs.append(o)
        for v in x.values(): walk(v)
    elif isinstance(x, list):
        for v in x: walk(v)
walk(data)
print('ref option groups/items', len(refs))
terms=['Homo sapiens','Human','hg19','hg38','GRCh37','GRCh38','hsapiens','NCBI36','hg18','CHM13']
seen=set()
for o in refs:
    text=json.dumps(o)
    if any(t.lower() in text.lower() for t in terms):
        s=json.dumps(o, ensure_ascii=False)
        if s not in seen:
            seen.add(s); print(s)
print('matched', len(seen))
